select id, paid_at, status, sum(amount) over (partition by order_id order by amount, id rows between unbounded preceding and current row) as running_amount, round(amount / sum(amount) over (partition by status), 4) as amount_share, row_number() over w_grp as seq_no, ntile(4) over (order by amount desc, id) as amount_bucket, round(amount / sum(amount) over (partition by method), 4) as amount_share_2 from payments where method not in ('cash', 'paypal', 'card') window w_grp as (partition by order_id order by paid_at, id);
